#!/data/data/com.termux/files/usr/bin/bash
# Repl v0.6.50: longer-stride diagonal procedural trot + no-pop review entry.
# One entrypoint, Termux Git only; approved walk and canonical Repl.glb unchanged.
set -Eeuo pipefail
CAMPAIGN=REPL_PROCEDURAL_TROT_STRIDE_START_v0.6.50
printf 'CAMPAIGN=%s\nAUTHORITY=TERMUX_GIT_SOURCE_ONLY\nCANONICAL_GLB_MUTATION=FORBIDDEN\n' "$CAMPAIGN"
for bin in python3 git sha256sum; do command -v "$bin" >/dev/null || { echo "BLOCKED:MISSING:$bin"; exit 2; }; done
export REPL_ENTRY_SCRIPT="$(readlink -f "$0")"
printf 'ENTRY_SHA256=%s\n' "$(sha256sum "$REPL_ENTRY_SCRIPT" | cut -d' ' -f1)"
T="$(mktemp -d "${TMPDIR:-/tmp}/repl-trot50-XXXXXXXX")"
trap 'rm -rf "$T"' EXIT
export REPL_PAYLOAD="$T"
python3 - <<'REPL50_BOOT'
